overlap(i) = (MinList(high[i], high[i+1]) - MaxList(low[i], low[i+1])) / (high[i] - low[i]);
avgOverlap = average of overlap(i) for i in 0..overlapBars-2;
isLarge = average(high - low, overlapBars) >= sizeMultiple * average(high - low, longerLookback);
avgOverlap >= minOverlap && isLarge

level = highest(high, rangeLookback)[reentryWindow + 1];
brokeOut = any close[i] > level for i in 1..reentryWindow;
brokeOut && close[0] < level

isKeyTime = false;
for each t in { keyTime1, keyTime2, keyTime3 }: isKeyTime = isKeyTime || absvalue(minutesOf(ctx.Time(0)) - minutesOf(t)) <= windowMinutes;
return isKeyTime
